WITH attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.starts_on >= pr.starts_on AND a.starts_on < pr.ends_on + INTERVAL '30' DAY), metrics AS (SELECT id, starts_on, ends_on, promo_id, promotion_promo_code, promotion_discount_pct, COUNT(promo_id) OVER w_hist AS last3_count_promo_id, SUM(promo_id) OVER w_hist AS last3_sum_promo_id, AVG(promo_id) OVER w_hist AS last3_avg_promo_id, SUM(promotion_discount_pct) OVER (PARTITION BY promotion_promo_code, promo_code ORDER BY discount_pct, id, promo_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_promotion_discount_pct FROM attributed WHERE promotion_promo_code = 'VIP' WINDOW w_hist AS (PARTITION BY promo_code ORDER BY promotion_discount_pct, id, promo_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), latest AS (SELECT id, starts_on, ends_on, promo_id, promotion_discount_pct FROM metrics QUALIFY ROW_NUMBER() OVER (PARTITION BY promotion_promo_code ORDER BY cumulative_promotion_discount_pct, id, promo_id) = 1), scored AS (SELECT id, promo_id, promotion_discount_pct, AVG(promo_id) OVER (ORDER BY promo_id, id, promo_id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS promo_id_avg_2_prior, ROW_NUMBER() OVER (ORDER BY promotion_discount_pct, id, promo_id) AS seq_no FROM latest), base AS (SELECT *, seq_no * promo_id AS seq_no_times_promo_id, promotion_discount_pct * promo_id_avg_2_prior AS promotion_discount_pct_times_promo_id_avg_2_prior FROM scored WHERE promotion_discount_pct < 0.16) SELECT id, promo_id, promotion_discount_pct, promo_id_avg_2_prior, seq_no_times_promo_id, promotion_discount_pct_times_promo_id_avg_2_prior FROM base ORDER BY promo_id DESC, promotion_discount_pct_times_promo_id_avg_2_prior
